import {make} from './factory.js';
export default [
make('B1',1,{t:'Zamonni vaziyatga qarab tanlash',goal:'Odat, hozirgi jarayon, o‘tgan voqea va hozirgi natijani bir xabarda ajratasiz.',context:'Ko‘ngilli o‘quvchi maktab kutubxonasidagi ishini tasvirlaydi.',rule:['Zamonni signal so‘zdan oldin maqsad bilan tanlang: odat — I help; jarayon — I am helping; tugallangan voqea — I helped; hozirgi natija — I have helped.','Bir matnda zamon almashishi xato emas: vaqt va vazifa o‘zgarsa shakl ham o‘zgaradi. Yesterday bilan tugallangan ishni Present Perfectga o‘tkazmang.','Have been to va have gone to farqini, holat fe’llarining odatiy simple shaklini va yordamchi fe’lni qayta tekshiring.'],pattern:'usually help → am helping now → helped yesterday → have finished',ex:['I help in the library every Friday.','Today I am checking the books.','Yesterday we moved two shelves.','We have finished the first shelf.','I know where the books belong.','Lola has gone to the office.'],v:['volunteer|ko‘ngilli|/ˌvɒlənˈtɪə/|work as a volunteer','shelf|tokcha|/ʃelf/|move a shelf','belong|tegishli bo‘lmoq|/bɪˈlɒŋ/|belong on a shelf','check|tekshirmoq|/tʃek/|check a list'],read:'I help in our school library every Friday. Usually, I return books to their shelves and help younger students find stories. This week we are changing the room, so today I am checking the labels instead. Yesterday we moved two shelves away from the window. We have finished the first shelf, but the second one still needs labels. Lola has gone to the office to print them. She will return soon. I know where most books belong because I have worked here for a year. A new volunteer is learning the system, and I am showing him one section at a time. He made two mistakes yesterday, but he understands the categories better now. Our teacher says that finishing quickly is less important than putting each book in a place readers can find. We are keeping a short record so that next week’s volunteers can continue our work.',rq:[['Bugun nega odatdagi ishini qilmayapti?','the room is being changed','the library has closed forever','he dislikes younger students','This week roomni o‘zgartirishmoqda; bugungi vazifa boshqa.'],['Nima tezlikdan muhimroq deb aytiladi?','putting books where readers can find them','printing more labels than needed','avoiding records','Ustoz ish maqsadini aniqlik bilan bog‘laydi.']],listen:'I usually help in the library on Fridays. Today I am checking labels because we are changing the room. We moved two shelves yesterday. We have finished one shelf. Lola has gone to the office to print the remaining labels, and she will return soon.',lq:[['Lola qaytganmi?','not yet','she returned yesterday','she has never left','Has gone va will return hali qaytmaganini ko‘rsatadi.'],['Nechta tokcha tugadi?','one','two','none','Finished one shelf.']],table:[['Odatdagi kun','Fridays'],['Bugungi vazifa','checking labels']],gap:'We ___ two shelves yesterday. (move)|moved',fix:'We have finished it yesterday.|We finished it yesterday.',mc:['Hozirgi natijaga mos gap?','We have finished the first shelf.','We have finish yesterday.','We were finish every Friday.','Natija hozirgi ishga bog‘liq.'],exit:[['I ___ in the library every Friday. (help)','help'],['Today I am ___ labels. (check)','checking'],['Yesterday we ___ the shelves. (move)','moved'],['Lola has gone to the office. U qayerda bo‘lishi mumkin?','away at the office','back here already','never at the office','Gone hozir ketganligini bildiradi.'],['Holat fe’lini tanlang.','I know the system.','I am knowing the system.','I knowed the system.','Know odatda simple.']],wtask:'Doimiy vazifangiz, bugungi ishingiz, kechagi o‘zgarish va hozirgi natijani bitta xabarda tushuntiring.',write:'I usually help in the school library on Fridays. I put returned books on the shelves and show younger students where to look. Today I am checking labels because we are changing the room. Yesterday we moved two shelves to make more space near the window. We have finished one section, but we still need labels for the other. My friend has gone to the office to print them. I know most categories now, although I made mistakes when I first started. We are keeping a short record so that the next group can continue the work without confusion.',speak:'Bir faoliyatingizni to‘rt vaqt nuqtasidan tasvirlang va sherigingizning aniqlashtiruvchi savoliga javob bering.',visual:'timeline'}),
make('B1',2,{t:'Present Perfect Continuous: jarayon va davomiylik',goal:'Yaqindan beri davom etayotgan faoliyatni natijadan ajratasiz.',context:'O‘quvchilar loyiha ustida uzoq vaqt ishlagani va nimalarni tugatganini solishtiradi.',rule:['Have/has been + -ing davom etgan faoliyatga e’tibor beradi: We have been working for an hour.','Have written three pages aniq tugallangan miqdorni aytadi. Have been writing jarayon va sarflangan vaqtni ta’kidlaydi.','Holat fe’llarida ko‘pincha perfect simple: I have known her for years. Doimiyligi ko‘rinadigan natija bilan bog‘langan jarayon hozir to‘xtagan bo‘lishi ham mumkin.'],pattern:'have been working for an hour / have written three pages',ex:['We have been working for an hour.','I have written three pages.','She has been learning English since spring.','He has been running, so he is tired.','I have known her for years.','How long have you been waiting?'],v:['progress|rivojlanish|/ˈprəʊɡres/|make progress','wait|kutmoq|/weɪt/|wait for a friend','since|… dan beri|/sɪns/|since spring','result|natija|/rɪˈzʌlt/|a clear result'],read:'Our group has been working on a local history project for two weeks. We have interviewed three neighbours and written six short reports. Ali has been checking dates since Monday, while Lola has been drawing a map. The map is not finished yet, but she has completed the main streets. We have been learning how to ask clearer questions. At first, our interviews were too long and did not have a clear purpose. Now we choose two important questions before each visit. Our teacher has known one of the neighbours for years and helped us arrange a meeting. Today we are tired because we have been walking around the town all morning. Still, we can see real progress: we have collected useful stories, and our map shows where each one happened. We plan to stop for the day and compare the reports tomorrow.',rq:[['Six reports qaysi jihatni ta’kidlaydi?','a completed amount','only the duration','a future plan','Have written six — tugallangan miqdor.'],['Nega charchagan?','they have been walking all morning','they have not slept for a month','the map is complete','Jarayon ko‘rinadigan hozirgi natijaga bog‘langan.']],listen:'We have been working for two weeks. We have written six reports and interviewed three neighbours. Lola has been drawing the map, but it is not finished. We are tired because we have been walking all morning.',lq:[['Tayyor hisobot soni?','six','two','three','Written six reports.'],['Xarita tugaganmi?','No','Yes','It was never started','Not finished.']],table:[['Ish muddati','two weeks'],['Hisobotlar','six']],gap:'She has ___ learning since spring.|been',fix:'I have been knowing her for years.|I have known her for years.',mc:['Jarayonga urg‘u beradigan gapni tanlang.','I have been writing all morning.','I have written three pages.','I wrote last year.','Been writing jarayon.'],exit:[['We have been ___ for an hour. (work)','working'],['I have ___ three pages. (write)','written'],['How long have you ___ waiting?','been'],['Aniq tugallangan miqdor qaysi?','I have written six reports.','I have been writing.','I am writing.','Six reports natijani o‘lchaydi.'],['Know uchun odatiy shakl?','have known','have been knowing','has knowing','Holat fe’li.']],wtask:'Loyihangiz davomiyligi va tugallangan natijalarini alohida ko‘rsatib hisobot yozing.',write:'We have been preparing a school exhibition for two weeks. I have written four short descriptions, and my friend has taken ten photos. She has been choosing the best pictures since Monday. We have not finished the display yet, but the main title is ready. I have been learning to check dates carefully because one of our first descriptions had a mistake. Our teacher has known the local guide for years, and the guide has helped us find reliable information. Today we are tired because we have been moving tables all morning. We will compare the remaining texts tomorrow before printing them.',speak:'How long …? va How many …? savollariga mos ikki shaklda javob bering.',visual:'timeline'}),
make('B1',3,{t:'Hikoya zamonlari va Past Perfect',goal:'Hikoyadagi avval, davom va asosiy voqeani aniq tartiblaysiz.',context:'Uchrashuvga kelganingizda nima avval bo‘lib o‘tganini tushuntirasiz.',rule:['Past Simple hikoyani oldinga yuritadi; Past Continuous fondagi jarayonni ko‘rsatadi.','Had + V3 boshqa o‘tmish nuqtasidan oldingi voqea: When I arrived, the bus had left.','Past Perfect har bir eski voqeaga kerak emas. Voqealar tartibi aniq bo‘lsa Past Simple ko‘pincha yetarli; avvalgi voqeani alohida ko‘rsatmoqchi bo‘lsangiz had + V3 ishlating.'],pattern:'When I arrived, the bus had left. / was waiting → arrived → had left earlier',ex:['When I arrived, the bus had left.','Lola was waiting outside.','She had checked the timetable.','We called the teacher.','I hadn’t saved the message.','After we had spoken, we chose another route.'],v:['route|yo‘nalish|/ruːt/|another route','timetable|jadval|/ˈtaɪmteɪbəl/|check a timetable','miss|ulgurmay qolmoq|/mɪs/|miss a bus','earlier|oldinroq|/ˈɜːliə/|leave earlier'],read:'I arrived at the station at nine, but the school bus had already left. Lola was waiting outside the ticket office. She had checked the timetable and knew that a public bus would leave in twenty minutes. I had not saved the teacher’s message, so I did not know the school bus was leaving early. We called the teacher and explained the mistake. While we were talking, another classmate arrived. He had missed the message too. The teacher did not ask us to rush across the city. Instead, she told us to take the public bus and meet the group at the museum entrance. We bought tickets, checked the route, and arrived safely. Later I saved the meeting information in my calendar. The problem taught me to check an arrangement before the day of the trip, not only when I reached the station.',rq:[['Avtobus so‘zlovchidan oldin ketganini qaysi shakl ko‘rsatadi?','had already left','was waiting','arrived safely','Had left boshqa o‘tmish nuqtasidan oldin.'],['Xulosa nima?','check arrangements in advance','always run across the city','never use public transport','Oxirgi gap oldindan tekshirish sabog‘ini beradi.']],listen:'When I arrived at nine, the school bus had left. Lola was waiting outside. She had checked the timetable. A public bus was leaving in twenty minutes. We called our teacher and agreed to meet at the museum.',lq:[['So‘zlovchi nechada kelgan?','nine','eight','ten','Arrived at nine.'],['Keyingi avtobus qancha vaqtda?','twenty minutes','an hour','five minutes','In twenty minutes.']],table:[['Kelish soati','nine'],['Yangi uchrashuv joyi','museum']],gap:'When I arrived, the bus ___ left.|had',fix:'She had went home.|She had gone home.',mc:['Avvalgi o‘tmish voqeasini tanlang.','The bus had left before I arrived.','The bus will leave yesterday.','The bus has left yesterday at nine.','Had left oldingi nuqta.'],exit:[['She had ___ the timetable. (check)','checked'],['We were ___ outside. (wait)','waiting'],['I ___ the teacher yesterday. (call)','called'],['Past Perfect tuzilmasi?','had + V3','was + base verb','did + V3','Had + past participle.'],['Hikoyadagi hamma gapga had kerakmi?','No','Yes','Always','Aniq ketma-ketlikda Past Simple yetishi mumkin.']],wtask:'Kichik tushunmovchilik haqidagi hikoyani yozing; kamida bir avvalgi voqea va bir fon harakatni ko‘rsating.',write:'I reached the library at four, but my friend had already left. I had written the wrong time in my notebook. Another student was waiting near the door and told me that the meeting had finished at three. I called my friend and explained the mistake. While we were talking, the librarian found the worksheet I needed. My friend had left it for me, so I could still do the task. I thanked them both and checked the next meeting time carefully. Since then, I have put important arrangements in my calendar and read them again the evening before.',speak:'Nima avval bo‘lganini sherigingiz tushunadigan tartibda hikoya qiling.',visual:'timeline'}),
make('B1',4,{t:'Used to: avvalgi odat va o‘zgarish',goal:'Hozir o‘zgargan eski odatni tasvirlaysiz.',context:'O‘quvchi bolalikdagi o‘qish odati bilan hozirgisini solishtiradi.',rule:['Used to + asosiy fe’l o‘tmishda odat yoki holat bo‘lgan, hozir odatda o‘zgarganini bildiradi.','Did you use to …? va didn’t use to … odatiy imtihon shakllari. Did kelganda use asosiy shaklda.','Be used to + ot/-ing esa ko‘nikkan bo‘lishni bildiradi. I used to walk va I am used to walking ikki boshqa ma’no.'],pattern:'used to read / didn’t use to read; am used to reading ≠ used to read',ex:['I used to read only comics.','Now I enjoy longer stories.','She used to live near school.','Did you use to walk there?','I didn’t use to keep notes.','I am used to studying in the library.'],v:['habit|odat|/ˈhæbɪt/|change a habit','longer|uzunroq|/ˈlɒŋɡə/|longer stories','keep notes|qayd yozib bormoq|/kiːp nəʊts/|keep useful notes','used to|avval odat bo‘lgan|/ˈjuːst tə/|used to read'],read:'When I was younger, I used to read only comics because longer stories seemed difficult. I didn’t use to write new words down. I would forget them and feel frustrated the next day. Last year our teacher showed us how to choose a short book with a topic we liked. I started reading a few pages each evening and keeping simple notes. Now I enjoy longer stories, and I am used to checking unfamiliar words after I have guessed their meaning. My friend used to live near school, but she moved to another part of town. We don’t study together every afternoon now, although we still meet at the weekend. Looking back, I can see that changing one small habit helped more than trying to read a very difficult book in a single night.',rq:[['O‘qishdagi o‘zgarishga nima yordam berdi?','a small regular habit','one very difficult book overnight','stopping all comics','Oxirgi xulosa kichik muntazam odatni ta’kidlaydi.'],['Am used to nimani bildiradi?','being accustomed now','a finished childhood event','a future decision','Hozir ko‘nikkan bo‘lish.']],listen:'I used to read only comics. I didn’t use to keep notes. Now I enjoy longer stories and write down new words. My friend used to live near school, but she moved away. We still meet at weekends.',lq:[['Avval nima qilmagan?','kept notes','read comics','met friends','Didn’t use to keep notes.'],['Do‘sti hozir ham yaqin yashaydimi?','No','Yes','The recording does not say','Moved away o‘zgarishni aytadi.']],table:[['Eski o‘qish turi','comics'],['Hozirgi odat','notes']],gap:'Did you ___ to walk there?|use',fix:'I am used to study here.|I am used to studying here.',mc:['O‘zgargan eski odat qaysi?','I used to read only comics.','I use read comics tomorrow.','I am use to read yesterday.','Used to eski odat.'],exit:[['I didn’t ___ to keep notes.','use'],['She used ___ live here.','to'],['I am used to ___ here. (study)','studying'],['Used to + qaysi shakl?','base verb','verb + ing always','V3','Used to live.'],['Be used to nimani bildiradi?','being accustomed','always a former habit','a prediction','Ko‘nikkan holat.']],wtask:'Eski va hozirgi odatingiz, o‘zgarish sababi va natijasini yozing.',write:'I used to leave my English practice until the weekend. I didn’t use to keep a notebook, so I often forgot useful words. A teacher suggested a smaller daily routine. Now I practise for fifteen minutes each evening and record two phrases I can use. I am used to checking the meaning from context before opening a dictionary. I still make mistakes, but I feel more confident because I can see my progress. This change did not happen in one day. Choosing a realistic task and repeating it helped me more than making a very large plan I could not follow.',speak:'Used to va now bilan hayotingizdagi ikki o‘zgarishni sabab bilan tushuntiring.',visual:'compare'}),
make('B1',5,{t:'Kelajak uchrashuvlari va taxminlar',goal:'Jadval, kelishilgan uchrashuv, niyat va taxminni farqlaysiz.',context:'Ta’lim ko‘rgazmasiga borish rejasini boshqalarga tushuntirasiz.',rule:['Jadvalda Present Simple: The train leaves at eight. Shaxsiy kelishilgan uchrashuvda Continuous: We’re meeting the guide at nine.','Going to oldindan niyat yoki dalilga tayangan taxmin. Will taklif, shu paytdagi qaror va taxmin uchun ishlatiladi.','Kelajak haqida vaqt bog‘lovchisidan keyin odatda present: I’ll call when I arrive. When I will arrive emas.'],pattern:'train leaves / we’re meeting / going to prepare / will help / when I arrive',ex:['The train leaves at eight.','We are meeting the guide at nine.','I am going to prepare questions.','I think the visit will be useful.','I’ll carry your bag.','I’ll call when I arrive.'],v:['arrangement|kelishilgan reja|/əˈreɪndʒmənt/|confirm an arrangement','prepare|tayyorlamoq|/prɪˈpeə/|prepare questions','confirm|tasdiqlamoq|/kənˈfɜːm/|confirm the time','exhibition|ko‘rgazma|/ˌeksɪˈbɪʃən/|visit an exhibition'],read:'Our group is visiting an education exhibition next Saturday. The train leaves at eight, and we are meeting our guide at nine. I am going to prepare questions about study habits because that topic matters to our club. Lola thinks the visit will help us choose better practice activities. Ali sees her large folder and offers to carry it. We have already confirmed the tickets, but we will check the timetable again the evening before. The organiser says that the demonstration starts at ten. After it finishes, we will have time to ask questions. I will call my parents when I arrive, and I will send them another message when we leave. Our teacher reminds us that a clear arrangement needs both a time and a place, not simply a promise to meet sometime in the morning.',rq:[['The train leaves qaysi turdagi kelajak?','a timetable','a sudden offer','an uncertain wish','Jadvaldagi vaqt.'],['Qanday reja aniq deyiladi?','one with a time and place','one without details','only a personal promise','Oxirgi gap time va place ni talab qiladi.']],listen:'The train leaves at eight. We are meeting the guide at nine, and the demonstration starts at ten. I am going to prepare questions. I’ll call home when I arrive.',lq:[['Demonstratsiya qachon?','ten','eight','nine','Starts at ten.'],['Qachon qo‘ng‘iroq qiladi?','when he arrives','before buying tickets','next month','When I arrive.']],table:[['Poyezd','eight'],['Gid bilan uchrashuv','nine']],gap:'I’ll call when I ___. (arrive)|arrive',fix:'I will call when I will arrive.|I will call when I arrive.',mc:['Jadvalni tanlang.','The train leaves at eight.','I’ll carry your bag.','I think it will be useful.','Train leaves — jadval.'],exit:[['We are ___ the guide. (meet)','meeting'],['I am going ___ prepare questions.','to'],['When it ___, we will ask questions. (finish)','finishes'],['Shu paytdagi taklif qaysi?','I’ll carry your bag.','The train leaves at eight.','We met yesterday.','Will taklif qiladi.'],['When qismida odatiy shakl?','present','will always','Past Perfect always','Kelajak vaqt bog‘lovchisidan keyin present.']],wtask:'Safar rejasi uchun jadval, kelishuv, niyat va qayta aloqa vaqtini yozing.',write:'Our group is visiting the exhibition on Saturday. The train leaves at eight, so we are meeting at the station at half past seven. I am going to prepare three questions about learning methods. My friend will bring our tickets, and I’ll carry the shared folder. I think the visit will be useful because we can try different activities. When we arrive, I’ll call our teacher to confirm that everyone is there. After the demonstration finishes, we will ask our questions and write short notes. Please check the meeting place tonight and tell me if you need help finding the station.',speak:'Uchrashuvni kelishing, reja va taxminni ajratib ayting.',visual:'timetable'}),
make('B1',6,{t:'First va Second Conditional: real va xayoliy',goal:'Haqiqiy ehtimol bilan hozirgi xayoliy vaziyatni ajratasiz.',context:'Kutubxona uchun real budjet va xayoliy katta budjet solishtiriladi.',rule:['First Conditional: If we get funding, we will buy books — amalga oshishi mumkin bo‘lgan kelajak.','Second Conditional: If we had more space, we would build a reading corner — hozirgi yoki kelajakdagi xayoliy holat. Past shakl bu yerda o‘tmish vaqtini majburiy bildirmaydi.','Would if qismida odatda ishlatilmaydi. If I were you maslahatda keng qo‘llanadi; was ham ayrim norasmiy kontekstlarda uchraydi.'],pattern:'If + present, will … / If + past, would …',ex:['If we get funding, we will buy books.','If we had more space, we would build a reading corner.','I would choose a quieter room.','If I were you, I would ask the teacher.','We will start if the plan is approved.','What would you do with a larger budget?'],v:['funding|mablag‘|/ˈfʌndɪŋ/|get funding','budget|budjet|/ˈbʌdʒɪt/|a larger budget','approve|ma’qullamoq|/əˈpruːv/|approve a plan','corner|burchak|/ˈkɔːnə/|a reading corner'],read:'Our school may give the reading club a small budget. If the plan is approved, we will buy ten new books and repair two chairs. That is a realistic plan for this term. During the meeting, Lola asks what we would do with a much larger budget. If we had more space, we would build a separate reading corner. Ali says he would buy comfortable chairs, while I would choose books in several languages. We know these ideas are not all possible now. The teacher asks us to separate the real request from our future wishes. If I were the organiser, I would explain how each purchase helps students rather than simply choosing the most expensive items. We finally agree to submit the small plan and keep the larger ideas for another discussion.',rq:[['Kichik budjet bilan real ish nima?','ten books and two repaired chairs','a new building','unlimited computers','First Conditionaldagi reja aniq kichik ishlar.'],['Second Conditional bu matnda nima qiladi?','explores imagined options','reports yesterday’s purchases','guarantees funding','Xayoliy katta budjet muhokamasi.']],listen:'If our plan is approved, we will buy ten books. If we had a larger budget, we would create a reading corner. For now, we will submit the small plan and keep the bigger ideas for later.',lq:[['Real kitob soni?','ten','twenty','one hundred','Ten books.'],['Katta reja hozir kafolatmi?','No','Yes','It is already complete','Had/would xayoliy holat.']],table:[['Real xarid','ten books'],['Xayoliy loyiha','reading corner']],gap:'If we had more space, we ___ build a corner.|would',fix:'If I would have money, I would buy books.|If I had money, I would buy books.',mc:['Real ehtimol qaysi?','If we get funding, we will start.','If we had funding, we would start.','We started last year.','Present + will real kelajak sharti.'],exit:[['If I ___ you, I would ask.','were'],['We ___ buy books if it is approved.','will'],['If we ___ more space, we would build it.','had'],['Second Conditionaldagi past har doim o‘tmishmi?','No','Yes','Only with had','Xayoliy hozirgi holat bo‘lishi mumkin.'],['If qismidagi to‘g‘ri shakl?','If we had money','If we would have money','If we would had money','Had + would result.']],wtask:'Real kichik reja va xayoliy kattaroq reja haqida tavsiya yozing.',write:'If our club receives a small budget, we will buy books that students have requested. We will repair two chairs as well. If we had more money and a larger room, we would create a quiet reading corner with several shelves. However, that is not possible this term. If I were the organiser, I would start with the most useful items and ask students to explain their choices. A realistic plan is easier to approve than a long list without reasons. We will keep the bigger ideas for next year and check whether the first purchases improve our club meetings.',speak:'Bitta real ehtimol va bitta xayoliy imkoniyatni sabab bilan solishtiring.',visual:'cause'}),
make('B1',7,{t:'Passive: ish va natijaga e’tibor',goal:'Present/Past Simple passiveda amalni bajaruvchidan ko‘ra natijani ko‘rsatasiz.',context:'Maktab gazetasi kitob yig‘ish tadbirini yoritadi.',rule:['Passive uchun be + V3: Books are collected; The room was cleaned. Be zamonga va egaga mos.','By bajaruvchini aytadi, lekin noma’lum yoki muhim bo‘lmasa tashlab ketiladi. Passive amal bajaruvchini taxmin qilishga ruxsat bermaydi.','Active: students collect books. Passive: books are collected by students. Obyekt yangi gap egasiga aylanganda ma’no saqlansin.'],pattern:'are collected / was cleaned; by + agent when relevant',ex:['Books are collected every Friday.','The room was cleaned yesterday.','New labels are printed in the office.','The poster was designed by Lola.','The tickets were checked at the door.','English is spoken in our club.'],v:['collect|yig‘moq|/kəˈlekt/|collect books','design|loyihalamoq|/dɪˈzaɪn/|design a poster','donate|ehson qilmoq|/dəʊˈneɪt/|donate a book','notice|e’lon|/ˈnəʊtɪs/|a school notice'],read:'Books are collected in our school every Friday. Students bring books they no longer need, and the titles are checked by a teacher. Last week, sixty books were donated. The room was cleaned before the boxes arrived, and new labels were printed in the office. The main poster was designed by Lola, who wanted the instructions to be clear. Damaged books are repaired if possible; books that cannot be used are kept separate. The notice does not name every person who carried a box because the report focuses on the result. However, it thanks the class that organised the event. The new books will be shared with younger readers next month. The teacher says that a useful report should make the process clear and avoid suggesting that a result happened without anyone’s work.',rq:[['Nega har bir tashuvchi nomi yo‘q?','the report focuses on the result','nobody carried boxes','the author knows no names','Passive fokusni natijaga ko‘chiradi.'],['Poster muallifi kim?','Lola','an unnamed teacher','Ali','By Lola aniq agent.']],listen:'Sixty books were donated last week. The room was cleaned before the boxes arrived. New labels were printed in the office. The main poster was designed by Lola. Damaged books are repaired if possible.',lq:[['Kitob soni?','sixty','sixteen','six','Sixty, sixteen emas.'],['Yorliqlar qayerda chop etildi?','the office','the station','the garden','Printed in the office.']],table:[['Kitoblar','sixty'],['Poster muallifi','Lola']],gap:'The poster was ___ by Lola. (design)|designed',fix:'The tickets were check.|The tickets were checked.',mc:['Passive tuzilmasini tanlang.','Books are collected.','Books collected are students.','Books are collect.','Be + V3.'],exit:[['The room ___ cleaned yesterday.','was'],['Books ___ collected every Friday.','are'],['The tickets were ___. (check)','checked'],['By nimani kiritadi?','the agent','only the date','the new object','Bajaruvchini.'],['Passive uchun zarur fe’l shakli?','V3','base only','-ing only','Past participle.']],wtask:'Bir maktab tadbiri haqida jarayon va natija fokusidagi qisqa yangilik yozing.',write:'A book collection event was organised at our school last Friday. Students brought books that younger readers could use. The titles were checked by two teachers, and damaged pages were repaired where possible. Sixty books were collected in total. The room was cleaned before the boxes arrived, and labels were printed in the office. A poster designed by our class explained how to donate a book. The report focuses on what was done, but the organisers also thanked the volunteers. Next month the books will be shared with the junior classes during their reading lessons.',speak:'Bir tadbirni active va passive shaklda ikki xil fokus bilan sharhlang.',visual:'sentence'}),
make('B1',8,{t:'Reported speech va savollarni yetkazish',goal:'Boshqaning xabari va savolini bevosita iqtibossiz aytasiz.',context:'To‘garak rahbarining xabari kelmagan do‘stga yetkaziladi.',rule:['O‘tgan reporting fe’ldan keyin shakl ko‘pincha orqaga siljiydi: She said, “I am ready” → She said she was ready. Mazmun hali haqiqiy bo‘lsa har doim backshift shart emas.','Say xabarni, tell odatda kimga aytilganini oladi: told me. Said me standart shakl emas.','Reported questionda savol tartibi emas, gap tartibi: She asked where I lived. Yes/no savolda if/whether. Olmosh, vaqt va joyni haqiqiy vaziyatga moslang.'],pattern:'said that … / told me … / asked where I lived / asked if I was ready',ex:['She said she was ready.','He told me the room was closed.','Lola asked where I lived.','The teacher asked if we were ready.','Ali said he would call later.','She told us to bring notebooks.'],v:['report|yetkazmoq|/rɪˈpɔːt/|report a message','later|keyinroq|/ˈleɪtə/|call later','whether|… yoki yo‘qmi|/ˈweðə/|ask whether','remind|eslatmoq|/rɪˈmaɪnd/|remind a friend'],read:'Ali missed the club meeting, so Lola sent him a summary. The teacher had said that Room 3 was closed and that the next meeting would be in the library. She had asked everyone to bring a notebook. Lola told Ali that they were preparing short talks about local places. Ali asked where the library entrance was and whether the meeting started at four. Lola explained that the entrance was near the park and that the meeting started at half past four. She did not repeat every sentence exactly, but she kept the important details. Before sending the message, she checked the time again. Ali thanked her and said he would prepare a photo for his talk. Reporting a message is useful only if the new listener can understand what to do.',rq:[['Uchrashuv nechada boshlanadi?','half past four','four','five','Lola 4:30 deb aniqlashtiradi.'],['Nega hamma gap so‘zma-so‘z berilmagan?','a summary keeps important details','she forgot the entire message','reported speech forbids facts','Vazifa amaliy mazmunni yetkazish.']],listen:'The teacher said the next meeting would be in the library. She told us to bring notebooks. Ali asked whether it started at four. Lola explained that it started at half past four, near the park entrance.',lq:[['Nima olib kelish aytilgan?','notebooks','food','tickets','Told us to bring notebooks.'],['Soat qaysi?','4:30','4:00','5:30','Half past four.']],table:[['Joy','library'],['Vaqt','4:30']],gap:'She ___ me she was ready. (tell, past)|told',fix:'She asked where did I live.|She asked where I lived.',mc:['Reported questionni tanlang.','He asked if I was ready.','He asked was I ready?','He asked if was I ready.','Gap tartibi I was.'],exit:[['He ___ me the room was closed.','told'],['She asked ___ we were ready.','if'],['Ali said he ___ call later.','would'],['Say bilan qaysi gap to‘g‘ri?','She said she was ready.','She said me ready.','She said to ready me.','Say + xabar.'],['Reported savolda tartib qanday?','statement order','inversion always','do/does always','Where I lived.']],wtask:'Ustozning xabarini kelmagan do‘stingizga muhim ma’lumotlarni saqlab yetkazing.',write:'Hi Ali, our teacher said that the next meeting would be in the library because Room 3 was closed. She told us to bring notebooks and asked us to prepare a short talk about a local place. You asked whether the meeting started at four. I checked again, and it starts at half past four. The entrance is near the park. The teacher also reminded us to choose one clear photo rather than many unrelated pictures. Please tell me if you need help finding the entrance. I can meet you outside ten minutes before the talk begins.',speak:'Qisqa xabarni tinglang va boshqa sherigingizga o‘z so‘zingiz bilan yetkazing.',visual:'dialogue'}),
make('B1',9,{t:'Defining relative clauses',goal:'Qaysi odam yoki narsa nazarda tutilganini relative clause bilan aniqlashtirasiz.',context:'Yo‘qolgan narsalar stolida bir buyumni aniq tasvirlaysiz.',rule:['Who odamlarga, which narsalarga, that ko‘pincha ikkalasiga ishlatiladi. Defining clause qaysi obyekt ekanini aniqlaydi.','Olmosh obyekt bo‘lsa tushishi mumkin: the book (that) I borrowed. Ega bo‘lsa tushmaydi: the student who helped me.','Bu aniqlovchi qism odatda vergul bilan ajratilmaydi. Relative olmoshdan keyin qo‘shimcha takroriy it/he ishlatmang.'],pattern:'the student who helped / the book (that) I borrowed / the place where we met',ex:['The student who helped me is here.','This is the book that I borrowed.','I need a bag which has a strong handle.','That is the place where we met.','The pen I lost was blue.','People who read often learn new words.'],v:['handle|dasta|/ˈhændəl/|a strong handle','identify|aniqlamoq|/aɪˈdentɪfaɪ/|identify an object','borrow|vaqtincha olmoq|/ˈbɒrəʊ/|the book I borrowed','lost property|yo‘qolgan-topilgan buyumlar|/lɒst ˈprɒpəti/|lost property desk'],read:'Several bags were left after the school exhibition. The bag that I lost has a small green label and a strong black handle. It is not the bag which has a picture of a bird. A student who helped at the entrance remembers where I put it. She shows me a table where people can collect lost property. On the table I see the book I borrowed from the library, but my bag is under a chair nearby. The assistant asks me to describe one item inside before returning it. I explain that there is a notebook which has my name on the first page. These details identify my bag more clearly than simply saying it is blue. A defining clause helps the listener know exactly which person, object or place I mean.',rq:[['Qaysi sumka yo‘qolgan?','the one with a green label and black handle','the one with a bird picture','any bag on the table','Defining tafsilotlar egani aniqlaydi.'],['Nega qo‘shimcha detal so‘raladi?','to identify the owner more clearly','to sell the bag','to change its colour','Aniq identifikatsiya uchun.']],listen:'My bag has a green label and a black handle. It isn’t the one with a bird picture. The student who helped at the entrance saw it under a chair. My notebook has my name on the first page.',lq:[['Yorliq rangi?','green','blue','red','Green label.'],['Sumka qayerda?','under a chair','on a bus','inside a cupboard','Under a chair.']],table:[['Yorliq','green'],['Dasta','black']],gap:'The student ___ helped me is here.|who|that',fix:'The book that I borrowed it is new.|The book that I borrowed is new.',mc:['Ega relative olmoshi tushishi mumkinmi?','No, not in “the student who helped”.','Yes, always.','Only if it is a person.','Who bu yerda helped ning egasi.'],exit:[['The book ___ I borrowed is new.','that'],['The person ___ helped is Lola.','who'],['The place ___ we met is near school.','where'],['Obyekt olmoshni tushirish mumkin bo‘lgan gap?','the book I borrowed','the student helped me (same relative meaning)','the room is bright','I borrowed bookda obyekt bo‘shlig‘i bor.'],['Defining qism odatda vergul oladimi?','No','Yes, always','Only after who','Identifikatsiya uchun zarur qism.']],wtask:'Topilgan buyum yoki kerakli odamni uch aniq relative clause bilan tasvirlang.',write:'I am looking for the notebook that I left in the reading room. It has a green cover and a label which shows my name. The student who was sitting near the window may have seen it. I borrowed a book from the library, and I put the notebook beside it. The page I need contains notes for tomorrow’s talk. Please ask at the desk where students collect lost property. If you find the notebook, leave it with the teacher who manages our club. These details should help identify it without opening someone else’s private work.',speak:'Bir buyumni boshqalardan farqlaydigan tafsilotlar bilan taniting.',visual:'sentence'})
,
make('B1',10,{t:'Modals: maslahat, ruxsat va ehtimol',goal:'Must, should, can va might ma’nolarini vaziyatga mos tanlaysiz.',context:'Loyiha uchun ustozga murojaat va safar noaniqligi muhokama qilinadi.',rule:['Should maslahat; must/have to kuchli zarurat; can ruxsat yoki imkoniyat. Bir shakl bir necha ma’no olishi mumkin, shuning uchun vaziyat muhim.','Might/may ehtimol, must xulosa uchun ham ishlatiladi: She must be busy — dalilga tayangan taxmin, bu buyruq emas.','Can’t deduction kuchli mumkin emas degan xulosa: That can’t be Ali; he is away. Mustn’t esa taqiq. Taxminni fakt sifatida sotmang.'],pattern:'must be busy / might arrive late / can’t be here / should ask',ex:['She must be busy.','Ali might arrive late.','That can’t be Ali; he is away.','You should ask before using the room.','We can borrow the projector.','We mustn’t share private photos.'],v:['evidence|dalil|/ˈevɪdəns/|based on evidence','permission|ruxsat|/pəˈmɪʃən/|ask permission','private|shaxsiy|/ˈpraɪvət/|private photos','busy|band|/ˈbɪzi/|a busy teacher'],read:'We want to show a short presentation in the library. We can borrow the projector, but we have to ask the teacher first. Lola says the teacher might be busy because she has two meetings today. Ali thinks we should send a clear message rather than interrupt her lesson. A student says that someone near the door must be our teacher. I reply that it can’t be her because she is teaching upstairs. We decide to wait for a reply. When we receive permission, we check the room and agree not to use classmates’ private photos without asking them. The teacher may attend our presentation, but she has not confirmed it. We therefore prepare a plan that works whether she comes or not. Different modal verbs help us separate rules, advice and uncertain information.',rq:[['Ustozning qatnashuvi aniqmi?','No, it is unconfirmed','Yes, she promised','She is forbidden','May attend va not confirmed noaniqlik.'],['Private photos qoidasining ma’nosi nima?','ask before sharing','all photos are public','sharing is always required','Ruxsat chegarasi.']],listen:'We can borrow the projector, but we must ask permission. The teacher might be busy. She may attend, but she has not confirmed it. We mustn’t share private photos without asking.',lq:[['Nima qarzga olinishi mumkin?','projector','a bus','tickets','Borrow the projector.'],['Qatnashuv holati qanday?','not confirmed','cancelled forever','certain','Has not confirmed it.']],table:[['Jihoz','projector'],['Kerakli narsa','permission']],gap:'She ___ be busy. (ehtimol)|might|may',fix:'She must to be busy.|She must be busy.',mc:['Dalilga tayangan xulosani tanlang.','She must be busy; her meeting is still running.','You mustn’t enter.','You should rest.','Must be bu yerda deduction.'],exit:[['We ___ ask permission. (maslahat)','should'],['She ___ be busy. (ehtimol)','might'],['That ___ be Ali; he is away.','can’t'],['Mustn’t ma’nosi?','prohibition','uncertain possibility','optional activity','Taqiq.'],['Might natijani kafolatlaydimi?','No','Yes','Always','Might noaniqlikni saqlaydi.']],wtask:'Loyiha uchun ruxsat, maslahat, ehtimol va dalilga tayangan bir xulosani ajratib yozing.',write:'We can borrow the school projector, but we must ask permission before using it. We should send the teacher a clear message with the place and time. She might be busy today, so we should not expect an immediate reply. The library must be available because its afternoon meeting has been cancelled, but we still need to confirm this. We mustn’t use private photos without asking the people in them. The teacher may attend our presentation, although that is not certain. We will prepare instructions for another organiser as well so that our plan does not depend on one person.',speak:'Bitta vaziyatda qoida, maslahat va taxminni turli modals bilan tushuntiring.',visual:'cause'}),
make('B1',11,{t:'Gerund/infinitive: ma’noni o‘zgartiradigan qolip',goal:'Stop, remember va try bilan -ing/to shaklining ma’noga ta’sirini ko‘rasiz.',context:'O‘quvchi o‘qish paytidagi chalg‘ish va eslab qolish usulini muhokama qiladi.',rule:['Stop doing — o‘sha ishni to‘xtatish. Stop to do — boshqa ishni vaqtincha to‘xtatib yangi ishni qilish: stopped to drink water.','Remember to do bajarishni unutmaslik, remember doing esa o‘tgan ish xotirasi. Bir-birini avtomatik almashtirmang.','Try to do urinib ko‘rish; try doing yechim sifatida bir usulni sinash bo‘lishi mumkin. Avoid/enjoy + -ing va decide/want + to qoliplarini takrorlang.'],pattern:'stop talking / stop to drink; remember to call / remember calling',ex:['I stopped checking my phone.','We stopped to drink water.','Remember to save your draft.','I remember meeting her last year.','Try reading the sentence aloud.','He tried to open the locked door.'],v:['draft|qoralama|/drɑːft/|save a draft','aloud|ovoz chiqarib|/əˈlaʊd/|read aloud','locked|qulflangan|/lɒkt/|a locked door','distract|chalg‘itmoq|/dɪˈstrækt/|distract a reader'],read:'I used to check my phone while doing homework. My teacher suggested stopping this habit for one short study session. I put the phone in another room and tried reading difficult sentences aloud. The change helped me notice missing words. After twenty minutes, I stopped to drink water, then returned to the task. Before closing the editor, I remembered to save my draft. Later I remembered writing one sentence differently, so I compared the two versions. My friend tried to open an old file but could not find it. She had forgotten to save it under a clear name. We learned that a small language difference can describe a different action: stopping a habit is not the same as stopping for a break, and remembering an experience is not the same as remembering to do a necessary job.',rq:[['Stopped to drink water nimani anglatadi?','paused another task for a drink','stopped drinking forever','forgot the water','To do yangi maqsadni beradi.'],['Nima matnni tekshirishga yordam berdi?','reading aloud','checking the phone more','closing without saving','Reading aloud missing wordsni sezishga yordam berdi.']],listen:'I stopped checking my phone and tried reading aloud. After twenty minutes, I stopped to drink water. I remembered to save my draft. My friend forgot to save hers and could not find the file later.',lq:[['Qaysi odat to‘xtadi?','checking the phone','drinking water','reading aloud','Stopped checking my phone.'],['Do‘stining muammosi nima?','forgot to save','saved twice','used a new font','Forgot to save.']],table:[['Sinov usuli','reading aloud'],['Tanaffusdan oldingi vaqt','twenty minutes']],gap:'Remember ___ save your draft.|to',fix:'I stopped to checking my phone.|I stopped checking my phone.',mc:['O‘tgan xotira qaysi?','I remember meeting her.','Remember to meet her tomorrow.','I will meet her.','Remember doing o‘tgan ish xotirasi.'],exit:[['I stopped ___ my phone. (check)','checking'],['We stopped ___ drink water.','to'],['I remember ___ her. (meet)','meeting'],['Try doing ko‘pincha nima?','testing a method','only a past success','a prohibition','Yechim usulini sinash.'],['Avoid bilan qolip?','avoid using','avoid to use','avoid uses','Avoid + -ing.']],wtask:'O‘qishdagi bir muammo, sinagan usulingiz va esdan chiqarmaslik kerak bo‘lgan ishni yozing.',write:'I had trouble noticing small mistakes in my writing. A teacher suggested trying to read the text aloud. I stopped checking my phone during the exercise and listened to each sentence. After a short time, I stopped to take a break. When I returned, I remembered to save my first draft before editing it. I remember writing one long sentence that was difficult to follow, so I divided it into two. The method did not correct every error, but it helped me focus. Next time I will try asking a friend to explain what they understood before I show them my own plan.',speak:'Bir ma’noli farqni ikki kichik voqea bilan tushuntiring.'}),
make('B1',12,{t:'Indirect questions: muloyim ma’lumot so‘rash',goal:'Do you know where …? bilan savolni muloyim va to‘g‘ri tartibda tuzasiz.',context:'Sayyoh axborot stolida yo‘l va jadval so‘raydi.',rule:['Indirect questionda ichki qism gap tartibida: Could you tell me where the station is? Is the station emas.','Yes/no savollar uchun if/whether: Do you know if the museum is open?','Asosiy savolning ohangi va tinish belgisi butun gapga tegishli. Could you tell me …? savol; I wonder … ko‘pincha xabar yoki o‘y.'],pattern:'Could you tell me where it is? / Do you know if it is open?',ex:['Could you tell me where the station is?','Do you know what time the train leaves?','I wonder if the museum is open.','Can you tell me how much a ticket costs?','Do you know whether we need to book?','Could you explain how this works?'],v:['information desk|axborot stoli|/ˌɪnfəˈmeɪʃən desk/|ask at the information desk','book|oldindan band qilmoq|/bʊk/|book a ticket','cost|narx turmoq|/kɒst/|how much it costs','wonder|o‘ylamoq, bilgisi kelmoq|/ˈwʌndə/|I wonder if'],read:'At the station, I asked at the information desk rather than guessing where to go. “Could you tell me what time the next train leaves?” The assistant said it left at eleven. I then asked how much a return ticket cost and whether I needed to book a seat. She explained that a ticket was available but a seat reservation would help on a busy day. Outside, my friend asked where the museum was. I did not know, so we returned to the desk. The assistant drew a simple route and told us to check the museum’s opening time. Asking a longer question did not make us less clear. It gave the other person a polite way to help while keeping the important question inside. We wrote down the answers and repeated them to confirm the details.',rq:[['Nega axborot stoliga bordi?','to ask instead of guessing','to buy a book','to leave luggage forever','Rather than guessing sabab.'],['Joy band qilish haqida nima deyiladi?','helpful on a busy day','impossible','always forbidden','Would help on a busy day, majburiy deyilmagan.']],listen:'Could you tell me what time the next train leaves? It leaves at eleven. Do you know whether I need to book a seat? A reservation is helpful on a busy day. The museum is open until five.',lq:[['Poyezd soati?','eleven','five','nine','Leaves at eleven.'],['Muzey nechagacha?','five','eleven','seven','Open until five.']],table:[['Poyezd','eleven'],['Muzey yopilish vaqti','five']],gap:'Do you know where the station ___?|is',fix:'Could you tell me where is the station?|Could you tell me where the station is?',mc:['Indirect yes/no savol qaysi?','Do you know if it is open?','Do you know is it open?','Do you know does it open is?','If + statement order.'],exit:[['Do you know ___ it is open?','if'],['Can you tell me how much it ___? (cost)','costs'],['What time the train ___ (leave)','leaves'],['Ichki savolda tartib?','subject before verb','verb before subject always','do before every verb','The station is.'],['Whether nimaga xizmat qiladi?','a yes/no indirect question','only a number','a command','If/whether yes/no ichki savol.']],wtask:'Safar uchun axborot xodimiga uch savolli odobli email yozing.',write:'Dear Information Team, I am planning a visit with two classmates next Saturday. Could you tell me what time the first train leaves from our station? I would also like to know how much a return ticket costs for students. Do you know whether we need to book our seats in advance? We hope to visit the museum after arriving, so could you tell me where its nearest entrance is? I have checked the timetable, but I want to confirm the weekend service before buying tickets. Thank you for your help. Best wishes, Lola.',speak:'Axborot stolida uch muloyim savol bering va javobni qayta tasdiqlang.',visual:'dialogue'}),
make('B1',13,{t:'Subject va object questions',goal:'Kim ishni bajarganini va kimga ta’sir qilganini turli savollar bilan so‘raysiz.',context:'Loyiha papkasini kim yuborganini aniqlaysiz.',rule:['Who called you? — who ega, do/did yordamchisi odatiy tasdiq savolda kerak emas. Who did you call? — you ega, who obyekt.','What happened? ega savoli; What did you see? obyekt savoli. Savoldagi noma’lum bo‘lakni avval toping.','Ega savolida fe’l mos shaklda qoladi: Who lives here? Obyekt savolda yordamchidan keyin asosiy fe’l: Who does she help?'],pattern:'Who sent it? ≠ Who did you send it to?',ex:['Who sent the file?','Who did you send the file to?','What happened?','What did you find?','Who lives near school?','Which student helped you?'],v:['send|yubormoq|/send/|send a file','receive|qabul qilmoq|/rɪˈsiːv/|receive a message','folder|papka|/ˈfəʊldə/|a shared folder','happen|sodir bo‘lmoq|/ˈhæpən/|what happened'],read:'Our group received a file without a clear name. The teacher asked, “Who sent it?” Lola said Ali had uploaded it after the meeting. The teacher then asked Ali who he had sent the link to. He had sent it to the whole group, but one classmate could not open it. We checked what had happened and found that the link was private. Ali changed the sharing setting only for our class, not for everyone on the internet. The teacher explained that two similar questions can ask about different roles. “Who sent the file?” asks for the sender. “Who did you send it to?” asks for the receiver. We added a clear title and date, checked the access again, and wrote a short note explaining which version to use.',rq:[['Who sent it? nimani so‘raydi?','the sender','the receiver','the date only','Who ega: yuboruvchi.'],['Bir o‘quvchi nega ocholmagan?','the link was private','the file did not exist','all internet was off','Private sharing sabab.']],listen:'Who sent the file? Ali sent it. Who did he send the link to? He sent it to the whole group. One student couldn’t open it because the link was private. We changed access for the class only.',lq:[['Yuboruvchi kim?','Ali','Lola','the teacher','Ali sent it.'],['Kimga ruxsat ochildi?','the class only','all internet users','nobody','Class only.']],table:[['Yuboruvchi','Ali'],['Qabul qiluvchilar','whole group']],gap:'Who ___ near school? (live)|lives',fix:'Who did sent the file?|Who sent the file?',mc:['Qabul qiluvchini so‘raydigan savol?','Who did you send it to?','Who sent it?','What happened?','Who obyekt, you ega.'],exit:[['What ___? (happen, past)','happened'],['Who ___ the file? (send, past)','sent'],['What did you ___? (find)','find'],['Ega savolni tanlang.','Who helped you?','Who did you help?','Who did you talk to?','Who helped — ega noma’lum.'],['Who does she help? da ega kim?','she','who','does','Who obyekt, she ega.']],wtask:'Bir loyiha voqeasi haqida yuboruvchi, oluvchi va natijani aniqlaydigan savol-javob yozing.',write:'Our group received a new folder yesterday. Who sent it? Ali uploaded the folder after the meeting. Who did he send the link to? He shared it with our class. What happened when Lola opened it? She could see the photos but not the text file. We checked the settings and found that one document was still private. Ali gave access to the class only, and Lola opened the right version. What did we learn? A clear file name and a simple access check save time, but sharing everything publicly is not a good solution.',speak:'Bir voqeaga ega va obyekt haqida ikkitadan savol bering.',visual:'sentence'}),
make('B1',14,{t:'Question tags va tasdiqlash ohangi',goal:'Qisqa tag bilan ma’lumotni tekshirasiz va suhbatni davom ettirasiz.',context:'Sinf tadbirining vaqtini va vazifalarini qayta tasdiqlaydi.',rule:['Tasdiq gapda odatda inkor tag, inkor gapda tasdiq tag: You are ready, aren’t you? You didn’t call, did you?','Tagda yordamchi fe’l va ega olmoshi saqlanadi. Present Simple harakatida do/does: She likes it, doesn’t she?','Ohang ma’noga ta’sir qiladi: ko‘tarilish ko‘proq tekshirish, pasayish ko‘proq kutayotgan tasdiq. I am …, aren’t I? maxsus odatiy shakl.'],pattern:'You’re ready, aren’t you? / She likes it, doesn’t she?',ex:['You are ready, aren’t you?','The meeting starts at four, doesn’t it?','Ali didn’t call, did he?','We can use this room, can’t we?','I am in the right place, aren’t I?','You have finished, haven’t you?'],v:['confirm|tasdiqlamoq|/kənˈfɜːm/|confirm a detail','expect|kutmoq|/ɪkˈspekt/|expect agreement','tone|ohang|/təʊn/|a rising tone','detail|tafsilot|/ˈdiːteɪl/|check a detail'],read:'Before the club presentation, Lola checks the arrangements. “The meeting starts at four, doesn’t it?” Ali looks at the notice and confirms the time. “We can use the library, can’t we?” she asks next. The teacher explains that the library is busy, so the meeting is in Room 5. Lola had expected agreement, but the tag helped reveal a wrong detail. Ali asks whether everyone has finished their slides. “You haven’t added the last photo, have you?” he asks one classmate. The classmate says the photo is ready but needs a caption. Their questions are not complaints. They are a way to check facts before the event. The teacher reminds them that a tag does not make a false statement true; the listener must still have room to disagree.',rq:[['Tag qaysi noto‘g‘ri detalni aniqladi?','the room','the presentation language','the date of birth','Library band, Room 5 ishlatiladi.'],['Tag nimani kafolatlamaydi?','that the statement is true','a chance to check','a short question','Tinglovchi e’tiroz qila olishi kerak.']],listen:'The meeting starts at four, doesn’t it? Yes. We can use the library, can’t we? No, it is busy. We are meeting in Room 5. You have finished your slides, haven’t you?',lq:[['Uchrashuv xonasi?','Room 5','the library','Room 4','Kutubxona band deb tuzatiladi.'],['Uchrashuv vaqti?','four','five','six','Starts at four.']],table:[['Vaqt','four'],['Xona','5']],gap:'She likes it, ___ she?|doesn’t',fix:'You are ready, don’t you?|You are ready, aren’t you?',mc:['Inkor gap tagini tanlang: He didn’t call, …','did he?','didn’t he?','does he?','Inkor gap → tasdiq did he.'],exit:[['We can use it, ___ we?','can’t'],['You have finished, ___ you?','haven’t'],['I am right, ___ I?','aren’t'],['Tagda qaysi ega shakli odatiy?','pronoun','full list of nouns','no subject','It/he/she/we kabi olmosh.'],['Tag yolg‘on fikrni to‘g‘ri qiladimi?','No','Yes','Always','Savol tasdiqni tekshiradi.']],wtask:'Tadbir tayyorgarligini tekshirish uchun uchta tag savoli va olingan javoblarni yozing.',write:'I checked our presentation plan with Ali. The meeting starts at four, doesn’t it? He confirmed the time. We can use the library, can’t we? That detail was wrong because another group had booked it. We are using Room 5 instead. You have finished the slides, haven’t you? Ali said he still needed one caption. We agreed to check it together before lunch. The questions helped us find problems without blaming anyone. I then wrote a clear message for the class so that everyone had the same room, time and task information.',speak:'Tagni ko‘tariluvchi va pasayuvchi ohang bilan ayting va javobdagi farqni muhokama qiling.',visual:'dialogue',pron:'Bir tagni chin savol ohangi va kutilayotgan tasdiq ohangi bilan ikki marta ayting.'}),
make('B1',15,{t:'-ed va -ing sifatlar; so va such',goal:'His qiluvchi odamni sabab bo‘luvchi narsadan ajratasiz.',context:'Ikki o‘quvchi film ko‘rgandan keyin fikr bildiradi.',rule:['Interested odamning his holati; interesting qiziqish uyg‘otuvchi narsaning belgisi. Bored va boring ham shu farqni ko‘rsatadi.','So + sifat/ravish: so interesting. Such + ot birikmasi: such an interesting film. A/an joylashuvini saqlang.','Too qanchaliklikdan tashqari muammo yoki ortiqlikni bildiradi. So interesting ijobiy, too difficult vazifaga ortiqcha qiyinlik bo‘lishi mumkin.'],pattern:'I’m interested because it’s interesting. / so good / such a good film',ex:['The film was interesting.','I was interested in the story.','The long introduction was boring.','We were bored at first.','It was such a useful discussion.','The ending was so surprising.'],v:['interested|qiziqqan|/ˈɪntrəstɪd/|interested in','surprising|hayrat uyg‘otadigan|/səˈpraɪzɪŋ/|a surprising ending','discussion|muhokama|/dɪˈskʌʃən/|a useful discussion','ending|yakun|/ˈendɪŋ/|the film’s ending'],read:'Our club watched a short film about a young inventor. The introduction was slow, so some students were bored at first. Once the main problem appeared, the story became interesting. I was interested in how the character tested different ideas rather than simply finding a perfect answer. The ending was surprising because his first plan failed, but a smaller change solved the problem. After the film, we had such a useful discussion that I wrote a page of notes. One student said the film was too difficult, while another said the pictures helped her understand it. We agreed that a review should explain these opinions, not only use words like good or bad. The film was entertaining, but the discussion helped us connect it to our own project mistakes.',rq:[['Nega so‘zlovchi qiziqdi?','the character tested ideas','the introduction was long','the film had no problem','Qiziqish sababini aniq tushuntiradi.'],['Foydali review nima qiladi?','explains opinions with reasons','only says good','lists all words','Matn reason talab qiladi.']],listen:'The introduction was boring, and we were bored. Then the story became interesting. I was interested in the inventor’s tests. The ending was so surprising, and we had such a useful discussion afterward.',lq:[['Boshida odamlar holati?','bored','boring','interested throughout','People were bored.'],['Yakun qanday?','surprising','unchanged','known from the start','So surprising.']],table:[['Kirish sifati','boring'],['Odamlar hissi','bored']],gap:'I am interested ___ science.|in',fix:'I was boring because the introduction was long. (his)|I was bored because the introduction was long.',mc:['Ot birikmasi bilan to‘g‘ri shakl?','such an interesting film','so an interesting film','such interesting an film','Such + an + sifat + ot.'],exit:[['The film was ___. (qiziqarli)','interesting'],['I was ___. (qiziqdim)','interested'],['such ___ useful discussion','a'],['So bilan mos qolip?','so surprising','so a surprising ending','such surprising without noun','So + sifat.'],['Hisni bildiradigan sifat qaysi?','bored','boring','entertaining','Bored his qiluvchi holat.']],wtask:'Film yoki kitob review yozing; his, sabab va bitta asoslangan tavsiya qo‘shing.',write:'I watched a short film about a student inventor. The introduction was rather boring, and I was bored during the first few minutes. However, the main story was interesting because it showed several failed experiments. I was interested in the way the character used feedback. The ending was so surprising that our group discussed it for half an hour. It was such a useful conversation because we could compare the mistakes with our own work. I recommend the film to students who enjoy practical projects. The language may be difficult in places, but the pictures make the main ideas clear.',speak:'Bir asarni taqqoslab, nimani his qilganingiz va nima sabab bo‘lganini tushuntiring.',visual:'compare'}),
make('B1',16,{t:'Although, however, while: sabab va farq',goal:'Bir-biriga zid yoki sababli fikrlarni ravon bog‘laysiz.',context:'Telefon bilan o‘qishning foydasi va chalg‘itishi baholanadi.',rule:['Although + gap qarama-qarshi ikki holatni bog‘laydi: Although it was difficult, I continued. Shu gapda qo‘shimcha but ko‘pincha kerak emas.','However ikki mustaqil fikrni bog‘lovchi diskurs vositasi. Yozuvda nuqta yoki mos ajratish ishlating; oddiy vergul bilan ikki gapni noto‘g‘ri yopishtirmang.','While taqqoslash yoki bir vaqtdagi ikki jarayonni bildirishi mumkin. Because sabab, so natija; sabab va natijani teskari qilib yubormang.'],pattern:'Although …, … . / … . However, … . / … because … / …, so …',ex:['Although the task was difficult, I continued.','The app is useful. However, it can distract me.','Lola likes audio, while Ali prefers reading.','I took notes because the talk was long.','The room was noisy, so we moved.','I practised until the instructions were clear.'],v:['distract|chalg‘itmoq|/dɪˈstrækt/|distract attention','prefer|afzal ko‘rmoq|/prɪˈfɜː/|prefer reading','continue|davom ettirmoq|/kənˈtɪnjuː/|continue working','attention|diqqat|/əˈtenʃən/|pay attention'],read:'Using a phone for English practice can be convenient because audio and dictionaries are easy to reach. However, the same device can distract us with messages. Lola prefers listening to short recordings, while Ali likes reading on paper. Neither method is best for every task. Although a learning app helps me practise vocabulary, I still need to use new phrases in conversation. Last week our study room was noisy, so we moved to the library. We switched off unrelated notifications and agreed on a clear aim for twenty minutes. The session went better because we knew what to finish. This does not mean phones are always bad or paper is always better. A useful choice depends on the task, the learner and the way the tool is used. We now discuss the purpose before choosing the device.',rq:[['Muallifning asosiy fikri?','choose tools according to purpose','phones are always bad','paper never helps','Oxirgi gap purpose-first tanlovni aytadi.'],['Nega joyni o‘zgartirishdi?','the room was noisy','the library had new chairs','the app stopped working','Noisy so moved — sabab/natija.']],listen:'The app is useful. However, messages can distract me. Lola prefers audio, while Ali likes paper. Our room was noisy, so we moved to the library. We worked better because we had a clear aim.',lq:[['Lola nimani afzal ko‘radi?','audio','paper','video games','Lola prefers audio.'],['Nega yaxshiroq ishladi?','a clear aim','more notifications','a larger phone','Because clear aim.']],table:[['Lola usuli','audio'],['Ali usuli','paper']],gap:'The room was noisy, ___ we moved.|so',fix:'Although it was difficult, but I continued.|Although it was difficult, I continued.',mc:['Farqni ravon bog‘lang.','Lola likes audio, while Ali prefers reading.','Lola likes audio because Ali prefers reading (cause).','Lola likes audio so while.','While bu yerda taqqoslash.'],exit:[['I continued ___ it was difficult.','although'],['I took notes ___ the talk was long.','because'],['The room was noisy, ___ we moved.','so'],['However bilan to‘g‘ri yozuv?','It is useful. However, it distracts me.','It useful however distracts.','Although however but useful.','Mustaqil fikrlar to‘g‘ri ajratiladi.'],['While faqat vaqt ma’nosidami?','No','Yes','Always','Taqqoslash ham bo‘ladi.']],wtask:'O‘qish usullaridan ikkitasini foyda va kamchiliklari bilan taqqoslang.',write:'I use both a phone and a notebook to study English. The phone is convenient because I can listen to recordings anywhere. However, messages sometimes distract me. My notebook is useful for keeping a few phrases together, while the phone helps me hear pronunciation. Although an app can show whether a short answer is correct, it cannot tell me everything about my speaking. I therefore practise with a classmate as well. Last week we chose one aim before our session and turned off unrelated notifications. We worked more carefully, so the session was more useful. The tool matters, but the purpose matters too.',speak:'Bir fikrga sabab, bir qarama-qarshi nuqtaga esa although/however qo‘shing.',visual:'argument'}),
make('B1',17,{t:'Collocations va phrasal verbsni qo‘llash',goal:'Make progress, take notes, catch up bilan vaziyatni tabiiy ifodalaysiz.',context:'Dars qoldirgan o‘quvchi guruhiga yetib oladi.',rule:['Collocation birga tabiiy ishlatiladigan so‘zlar: make progress, take notes, do homework. Har birini o‘zbekchadan so‘zma-so‘z ko‘chirmang.','Catch up with — ortda qolgan qismga yetishish; hand in — topshirish; look up — tekshirib topish. Birikmani kontekst va to‘ldiruvchi bilan o‘rganing.','Ajraladigan phrasal verbda olmosh o‘rtada: hand it in, look it up. Catch up with classmates esa boshqa qolip.'],pattern:'make progress / take notes / do homework / hand it in / catch up with',ex:['I am making progress.','She takes notes during the talk.','We do homework after dinner.','Please hand it in on Friday.','I need to catch up with my class.','Look the word up in a dictionary.'],v:['make progress|rivojlanmoq|/meɪk ˈprəʊɡres/|make steady progress','take notes|qayd yozmoq|/teɪk nəʊts/|take clear notes','hand in|topshirmoq|/hænd ɪn/|hand it in','catch up with|yetib olmoq|/kætʃ ʌp wɪð/|catch up with the class'],read:'Ali missed two lessons while visiting his grandparents. When he returned, he wanted to catch up with his class without copying all the answers. Lola gave him her notes and explained the main task. He looked up unfamiliar words and tried one example on his own. During the next talk, he took notes using short phrases rather than writing every sentence. His teacher asked him to hand the work in on Friday. Ali was making progress, but he still confused some common word combinations. He wrote “do progress” in one paragraph. The teacher corrected it to “make progress” and asked him to use the phrase in a new sentence about his own work. Learning the combination inside a real message helped him remember it. By Friday, he had finished the missing task and could explain the idea to another student.',rq:[['Ali nega javoblarni ko‘chirmadi?','he wanted to understand and catch up','the teacher hid all notes','he disliked the subject','O‘z misolini sinaydi, maqsad tushunish.'],['Qanday so‘z birikmasi tuzatildi?','do progress → make progress','take notes → make notes only','hand in → get up','Make progress tabiiy birikma.']],listen:'Ali needs to catch up with the class. He takes notes, looks up unfamiliar words, and does homework. He is making progress. The teacher asks him to hand it in on Friday.',lq:[['Topshirish kuni?','Friday','Monday','Sunday','Hand it in on Friday.'],['Qaysi birikma rivojlanishni bildiradi?','make progress','do progress','take progress','Make progress.']],table:[['Muddat','Friday'],['Ortda qolish yechimi','catch up']],gap:'I am ___ progress. (make)|making',fix:'Please hand in it.|Please hand it in.',mc:['Tabiiy birikmani tanlang.','take notes','do notes (during a talk)','take homework','Take notes.'],exit:[['___ homework','do'],['___ progress','make'],['Hand ___ in. (it)','it'],['Ortda qolgan guruhga yetishmoq?','catch up with','look down at','take after only','Catch up with class.'],['Lug‘atda so‘z tekshirish?','look it up','look up it','hand it off','Look it up, olmosh o‘rtada.']],wtask:'Dars qoldirgandan keyingi rejangizni kamida to‘rtta tabiiy birikma bilan yozing.',write:'I missed two lessons last week, so I need to catch up with my class. First, I will read the teacher’s summary and take notes on the main points. I will look unfamiliar words up and try one exercise without looking at the answer. Then I will do the homework and ask a classmate to check whether my explanation is clear. I have to hand it in on Friday. I am already making progress because I can describe the first topic in my own words. I will keep the useful phrases in my notebook and use them in a new message tomorrow.',speak:'O‘qish muammosini ayting va to‘rtta birikma bilan yechim taklif qiling.'}),
make('B1',18,{t:'Tajriba, fikr va asoslangan tavsiya',goal:'O‘z tajribangizga tayangan fikrni sabab, misol va cheklov bilan ifodalaysiz.',context:'Maktab klubiga yangi o‘qish usuli tavsiya qilinadi.',rule:['Opinion → reason → example → balanced conclusion fikrni tushunarli rivojlantiradi. I think deyishning o‘zi dalil emas.','O‘z tajribangizni boshqa odamlar uchun universal natija deb bermang. For me, in our group, may help kabi chegaralar aniqlikni oshiradi.','B1da bog‘langan nutq maqsad: o‘tmish tajribasi, hozirgi natija, tavsiya va savol. Mukammal gap yodlashdan ko‘ra ma’no va aloqa muhim.'],pattern:'I think … because … . For example, … . However, … . I suggest … .',ex:['I think short daily practice is useful.','It helps because the task is manageable.','For example, I remember more phrases now.','However, different learners need different plans.','I suggest trying it for a week.','What would you change in this plan?'],v:['manageable|bajarish mumkin bo‘lgan|/ˈmænɪdʒəbəl/|a manageable task','suggest|taklif qilmoq|/səˈdʒest/|suggest trying','experience|tajriba|/ɪkˈspɪəriəns/|personal experience','balanced|muvozanatli|/ˈbælənst/|a balanced view'],read:'Our reading club is deciding whether to practise for a long time once a week or for a short time every day. I used to study only at weekends and often forgot the words I had learned. This term I have been practising for fifteen minutes each evening. I have remembered more useful phrases, and I can use some of them in conversation. For me, the smaller task is easier to start. However, a friend has a busy evening routine and prefers two longer sessions. Her plan works because she reviews the material between meetings. We should not choose one method only because it worked for one person. I suggest trying a short daily routine for a week, recording the tasks we complete, and then comparing what we can actually do. The aim is not to count minutes alone but to notice whether we understand and use the language better.',rq:[['Muallif nima taklif qiladi?','test a routine and compare actual skills','force one method on everyone','count only minutes','Sinov va real ko‘nikma asosidagi taqqoslash.'],['Nega ehtiyotkor xulosa beradi?','learners have different routines','no method can ever work','the club has no members','Do‘stining boshqa rejasi ishlaydi.']],listen:'I have tried fifteen minutes of practice each day, and I remember more phrases. However, my friend prefers two longer sessions. I suggest testing a routine for a week and comparing what we can do, not just how many minutes we study.',lq:[['Qancha kundalik vaqt?','fifteen minutes','fifty minutes','two hours','Fifteen, fifty emas.'],['Nimani solishtirish kerak?','what learners can do','only minutes','only word count','Actual ability.']],table:[['Sinov muddati','a week'],['Kunlik vaqt','fifteen minutes']],gap:'I suggest ___ it for a week. (try)|trying',fix:'My method works for me, so it must work for everyone.|My method works for me, but it may not work for everyone.',mc:['Eng muvozanatli xulosa?','Try the routine and compare results for your needs.','Everyone must follow my plan.','Only minutes prove your level.','Dalil va cheklovga tayangan xulosa.'],exit:[['I have been ___ daily. (practise)','practising'],['I suggest ___ it. (try)','trying'],['It helps ___ the task is manageable.','because'],['Dalil qaysi?','a specific example from experience','only “I think”','a repeated opinion','Misol fikrni asoslaydi.'],['Bitta shaxs tajribasi hamma uchun kafolatmi?','No','Yes','Always','Cheklovni aytish zarur.']],wtask:'B1 loyiha: o‘qish usuli haqida tajriba, dalil, boshqa fikr va amaliy tavsiya yozing.',write:'I think short daily practice is useful because it is easier to fit into a normal day. I used to study only at the weekend and forgot many phrases. This term I have been practising for fifteen minutes each evening, and I can use more phrases in conversation. For example, I now ask for directions without reading a model. However, my friend prefers two longer sessions because her evenings are busy. I suggest testing a routine for one week and recording what we can actually do. A method should help us understand and communicate, not simply collect a large number of minutes.',speak:'Tavsiyangizni ikki daqiqagacha ayting, e’tirozga javob bering va yakuniy fikrni aniqlashtiring.',real:'Sherigingizning bir boshqa fikrini tinglang, uni xolis qayta ayting va tavsiyangizga qo‘shing.',visual:'argument'})
];
